INSERT INTO content.grammar_furigana (text_hash, text, segments)
VALUES
  ('d08763419252898434efe1440379479349435e917fed3eaae833e19b0626f712', 'バスで行きます "go by bus", はしで食べます "eat with chopsticks", 日本語で話します "speak in Japanese".', '[{"t":"バスで"},{"t":"行","r":"い"},{"t":"きます"},{"t":" \"go by bus\", "},{"t":"はしで"},{"t":"食","r":"た"},{"t":"べます"},{"t":" \"eat with chopsticks\", "},{"t":"日本語","r":"にほんご"},{"t":"で"},{"t":"話","r":"はな"},{"t":"します"},{"t":" \"speak in Japanese\"."}]'::jsonb),
  ('b7f7449cfd4e09a3bc0e536ac65e95105f9c2c8eeaf2f4a71fb21e50163b8e51', '使役形 (causative)', '[{"t":"使","r":"つか"},{"t":"役","r":"えき"},{"t":"形","r":"なり"},{"t":" (causative)"}]'::jsonb),
  ('dac38043546f43b7b5784ae6d0a2bec11e32ae475fca2b0351ad1c5b707fb49f', '五段 shift -u to -aseru: 行く → 行かせる. 一段 take させる: 食べる → 食べさせる. The person made to act takes に or を.', '[{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" shift -u to -aseru: "},{"t":"行","r":"い"},{"t":"く"},{"t":" → "},{"t":"行","r":"い"},{"t":"かせる"},{"t":". "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" take "},{"t":"させる"},{"t":": "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べさせる"},{"t":". The person made to act takes "},{"t":"に"},{"t":" or "},{"t":"を"},{"t":"."}]'::jsonb),
  ('8136a26281f46ab450bf5d43347e1a2a3beafca8e9dd7389878038fade2868d6', 'に and を are not interchangeable: 子どもを行かせる makes them go, 子どもに行かせる lets them. The particle carries the whole difference between coercion and permission.', '[{"t":"に"},{"t":" and "},{"t":"を"},{"t":" are not interchangeable: "},{"t":"子","r":"こ"},{"t":"どもを"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" makes them go, "},{"t":"子","r":"こ"},{"t":"どもに"},{"t":"行","r":"い"},{"t":"かせる"},{"t":" lets them. The particle carries the whole difference between coercion and permission."}]'::jsonb),
  ('c2d42131741ec3a25d71b0115d28df884948943580cf60e775090e5e64bd9bb8', '可能形 (potential)', '[{"t":"可能","r":"かのう"},{"t":"形","r":"なり"},{"t":" (potential)"}]'::jsonb),
  ('e9750df7ea6babbb29f12ee4858f7193e0d7cba8e740f05f2bf940ef7b26be6b', '五段 verbs shift the final -u to -eru: 書く → 書ける, 飲む → 飲める. 一段 verbs take られる: 食べる → 食べられる. する → できる, 来る → 来られる.', '[{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" verbs shift the final -u to -eru: "},{"t":"書","r":"か"},{"t":"く"},{"t":" → "},{"t":"書","r":"か"},{"t":"ける"},{"t":", "},{"t":"飲","r":"の"},{"t":"む"},{"t":" → "},{"t":"飲","r":"の"},{"t":"める"},{"t":". "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" verbs take "},{"t":"られる"},{"t":": "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べられる"},{"t":". "},{"t":"する"},{"t":" → "},{"t":"できる"},{"t":", "},{"t":"来","r":"く"},{"t":"る"},{"t":" → "},{"t":"来","r":"らい"},{"t":"られる"},{"t":"."}]'::jsonb),
  ('c60114b8929cb0fd7918782854d56c0d8b16ef7db7611593428e284d50b18277', 'The object of a potential verb usually takes が, not を: 日本語が話せます. The verb has stopped describing an action and started describing a capability, and capabilities are states.', '[{"t":"The object of a potential verb usually takes "},{"t":"が"},{"t":", not "},{"t":"を"},{"t":": "},{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"話","r":"わ"},{"t":"せます"},{"t":". The verb has stopped describing an action and started describing a capability, and capabilities are states."}]'::jsonb),
  ('ad2dd1dff9599ad306cda1dc2f5ff9db7255db3e888b71ede437ec56caeda2ac', 'ら抜き言葉', '[{"t":"ら"},{"t":"抜","r":"ぬ"},{"t":"き"},{"t":"言葉","r":"ことば"}]'::jsonb),
  ('b61db854ad01bc5f1c1e4b1c672edd3f27129191ac923e023769979b499c2fbb', '食べられる → 食べれる', '[{"t":"食","r":"た"},{"t":"べられる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べれる"}]'::jsonb),
  ('ad809b5923f786443e97294c31bf8ca6f6b7672836258d3fa8a77a879e9bf398', 'Colloquially the ら is dropped from 一段 potentials: 食べられる → 食べれる, 見られる → 見れる. Widespread in speech, still marked as incorrect in writing and on the exam.', '[{"t":"Colloquially the "},{"t":"ら"},{"t":" is dropped from "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" potentials: "},{"t":"食","r":"た"},{"t":"べられる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べれる"},{"t":", "},{"t":"見","r":"み"},{"t":"られる"},{"t":" → "},{"t":"見","r":"み"},{"t":"れる"},{"t":". Widespread in speech, still marked as incorrect in writing and on the exam."}]'::jsonb),
  ('67c038943bd28f71f75c03ac1db65c26ca4d1f71b702c6ceea2ee148cfb2105a', 'It is not laziness but a repair: 食べられる is potential AND passive AND honorific at once. Dropping ら gives the potential a form of its own, which is exactly the ambiguity the standard language leaves unresolved.', '[{"t":"It is not laziness but a repair: "},{"t":"食","r":"た"},{"t":"べられる"},{"t":" is potential AND passive AND honorific at once. Dropping "},{"t":"ら"},{"t":" gives the potential a form of its own, which is exactly the ambiguity the standard language leaves unresolved."}]'::jsonb),
  ('137a14f3af00da72a44bcd9a67b4af283b7f69857db5a993f94fcb1dffdab21c', '意向形 (volitional)', '[{"t":"意向","r":"いこう"},{"t":"形","r":"なり"},{"t":" (volitional)"}]'::jsonb),
  ('4381d2f1356ada58bd1bf2f9d472438bb56058cc09d6b4f70c431a1d1ca8c26e', '五段 shift -u to -ou: 行く → 行こう. 一段 take よう: 食べる → 食べよう. する → しよう, 来る → 来よう. The polite equivalent is ましょう.', '[{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" shift -u to -ou: "},{"t":"行","r":"い"},{"t":"く"},{"t":" → "},{"t":"行","r":"い"},{"t":"こう"},{"t":". "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" take "},{"t":"よう"},{"t":": "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べよう"},{"t":". "},{"t":"する"},{"t":" → "},{"t":"しよう"},{"t":", "},{"t":"来","r":"く"},{"t":"る"},{"t":" → "},{"t":"来","r":"らい"},{"t":"よう"},{"t":". The polite equivalent is "},{"t":"ましょう"},{"t":"."}]'::jsonb),
  ('62963dc29fe644ef6dfa1e67239f24c83fa83e208c1f72a5a0c8bed31a930696', 'Alone it is a proposal to whoever is present. With と思う it becomes a decision you have reached yourself: 行こうと思う, "I''ve decided to go".', '[{"t":"Alone it is a proposal to whoever is present. With "},{"t":"と"},{"t":"思","r":"おも"},{"t":"う"},{"t":" it becomes a decision you have reached yourself: "},{"t":"行","r":"い"},{"t":"こうと"},{"t":"思","r":"おも"},{"t":"う"},{"t":", \"I''ve decided to go\"."}]'::jsonb),
  ('ad9130e0d1986082b938ba24ed08f97385bdecc7a75614dd2ad9c62f3131ed71', '明日は晴れるでしょう. でしょう is the polite form.', '[{"t":"明日","r":"あした"},{"t":"は"},{"t":"晴","r":"は"},{"t":"れるでしょう"},{"t":". "},{"t":"でしょう"},{"t":" is the polite form."}]'::jsonb),
  ('974930f5c133901e4ed9a8c8d5ce6f0022d51de3e05ecb6e0f124525b3217fcc', 'With rising intonation it stops guessing and starts seeking agreement: 行くでしょう？ is closer to "you''re going, right?". Weather forecasts use it constantly for the plain probability sense.', '[{"t":"With rising intonation it stops guessing and starts seeking agreement: "},{"t":"行","r":"い"},{"t":"くでしょう"},{"t":"？ is closer to \"you''re going, right?\". Weather forecasts use it constantly for the plain probability sense."}]'::jsonb),
  ('e3201662ac9dd3a713e7f632ba84ffeb16144980366cbf7d5df499081d39c9a3', '彼は来ないらしい. A second use is "typical of": 男らしい, 春らしい一日.', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"来","r":"らい"},{"t":"ないらしい"},{"t":". A second use is \"typical of\": "},{"t":"男","r":"だん"},{"t":"らしい"},{"t":", "},{"t":"春","r":"はる"},{"t":"らしい"},{"t":"一日","r":"いちにち"},{"t":"."}]'::jsonb),
  ('29cce389a83193de8fd721981cf1863c5fb85acb2e272ea448e411aa9f746287', 'The two uses share a logic: both say something matches what is expected of its type. 春らしい日 is a day behaving as spring should.', '[{"t":"The two uses share a logic: both say something matches what is expected of its type. "},{"t":"春","r":"はる"},{"t":"らしい"},{"t":"日","r":"にち"},{"t":" is a day behaving as spring should."}]'::jsonb),
  ('3fcb9102f54f31cd8e17f622a99b8eaba9f15fc904cfd50a957c330f5d90d177', '〜予定', '[{"t":"〜"},{"t":"予定","r":"よてい"}]'::jsonb),
  ('50a113a1011c3fa21a6399388c98bcf50a0f0e0def78f58052eb2cdebb428d0f', 'Plain form / Noun の + 予定', '[{"t":"Plain form / Noun "},{"t":"の"},{"t":" + "},{"t":"予定","r":"よてい"}]'::jsonb),
  ('aa637c5cba637da13bd0e83407123a0caf6acea9f0a7ba0a850dc3a0431683bd', '三時に会議をする予定です. Also as a noun: 明日の予定.', '[{"t":"三","r":"さん"},{"t":"時","r":"とき"},{"t":"に"},{"t":"会議","r":"かいぎ"},{"t":"をする"},{"t":"予定","r":"よてい"},{"t":"です"},{"t":". Also as a noun: "},{"t":"明日","r":"あした"},{"t":"の"},{"t":"予定","r":"よてい"},{"t":"."}]'::jsonb),
  ('e9955d15ce49fae78c7ac23638fc10dac6c471e7607c1e49597f36305ac2e873', 'A 予定 exists independently of you wanting it. It is what the diary says, which is why it sounds neutral where つもり sounds personal.', '[{"t":"A "},{"t":"予定","r":"よてい"},{"t":" exists independently of you wanting it. It is what the diary says, which is why it sounds neutral where "},{"t":"つもり"},{"t":" sounds personal."}]'::jsonb),
  ('1d797952be6ae97f4036d7264fa9dc16ad80e6c971c33c781d717f78c68e0af3', '君の名前、何だっけ？', '[{"t":"君","r":"ぎみ"},{"t":"の"},{"t":"名前","r":"なまえ"},{"t":"、"},{"t":"何","r":"なん"},{"t":"だっけ"},{"t":"？"}]'::jsonb),
  ('5e9ac7841b23360d0c51a103e468cb9654c0f51b2d14078a61e4cc69a655deb3', '〜方 (かた)', '[{"t":"〜"},{"t":"方","r":"かた"},{"t":" ("},{"t":"かた"},{"t":")"}]'::jsonb),
  ('4209cbc9dbf12835f6bba9ba21076467dfefe8d5ba401757d309ebf05867f0e2', 'Verb stem + 方', '[{"t":"Verb stem + "},{"t":"方","r":"かた"}]'::jsonb),
  ('f00d66a21a7933d5662dbf03888acca552f5dab1e4c14d06ebf56a2f35449210', '使い方, 作り方. The result is a noun, so を becomes の: 漢字の書き方.', '[{"t":"使","r":"つか"},{"t":"い"},{"t":"方","r":"かた"},{"t":", "},{"t":"作","r":"づく"},{"t":"り"},{"t":"方","r":"かた"},{"t":". The result is a noun, so "},{"t":"を"},{"t":" becomes "},{"t":"の"},{"t":": "},{"t":"漢字","r":"かんじ"},{"t":"の"},{"t":"書","r":"か"},{"t":"き"},{"t":"方","r":"かた"},{"t":"."}]'::jsonb),
  ('594e88fc5a30157e682653a0ca5e0a3d4f7f53c4adab80ea90e1276747546998', 'The particle shift is the giveaway that the verb has become a noun. 漢字を書き方 is a common early mistake for exactly that reason.', '[{"t":"The particle shift is the giveaway that the verb has become a noun. "},{"t":"漢字","r":"かんじ"},{"t":"を"},{"t":"書","r":"か"},{"t":"き"},{"t":"方","r":"かた"},{"t":" is a common early mistake for exactly that reason."}]'::jsonb),
  ('b5476cf1c2a4448188dcfcb5f8bb06acfde2f06b105cea24b887b4079eb356bb', '忘れてはならない.', '[{"t":"忘","r":"わす"},{"t":"れてはならない"},{"t":"."}]'::jsonb),
  ('d7191926917a4c6efe329170f57d2571edb0eb3431e1d3e4b093d1c6ee3cc651', '寒くなっていく, "it will keep getting colder". 寒くなってきた, "it has been getting colder".', '[{"t":"寒","r":"さむ"},{"t":"くなっていく"},{"t":", \"it will keep getting colder\". "},{"t":"寒","r":"さむ"},{"t":"くなってきた"},{"t":", \"it has been getting colder\"."}]'::jsonb),
  ('2a3826a1a3a274e96d5ef2a59f1251f5d1dc66d818ba8a7aa090f5f7b00cf3a4', '友だちが手伝ってくれました. Honorific: 〜てくださる.', '[{"t":"友","r":"ゆう"},{"t":"だちが"},{"t":"手","r":"て"},{"t":"伝","r":"つた"},{"t":"ってくれました"},{"t":". Honorific: 〜"},{"t":"てくださる"},{"t":"."}]'::jsonb),
  ('ca159247a642b937b9bd04a68bd6398c7a54d4ce23247edccc937e08e8411a0c', '〜と思う', '[{"t":"〜"},{"t":"と"},{"t":"思","r":"おも"},{"t":"う"}]'::jsonb),
  ('05ad5524e1a9b58df0fe99748dca57ef690889412c0fabcb62ff67114ce4ed76', 'Plain form + と思う', '[{"t":"Plain form + "},{"t":"と"},{"t":"思","r":"おも"},{"t":"う"}]'::jsonb),
  ('86dba02076500eb1dbf6ed1c011c7701b82f53b0c242998a3048025e36341e29', '彼は正しいと思います. と marks the quoted thought, so the clause before it stays plain even when the sentence is polite.', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"正","r":"ただ"},{"t":"しいと"},{"t":"思","r":"おも"},{"t":"います"},{"t":". "},{"t":"と"},{"t":" marks the quoted thought, so the clause before it stays plain even when the sentence is polite."}]'::jsonb),
  ('b85c4301dba6105b17ee680e264cee9e7ea866cfdd5b0b345df5a2b7392dfc26', 'Japanese is strict about whose mind it is. 思う reports your own thought; for someone else you need 思っている, because you can only observe another person thinking, not do it.', '[{"t":"Japanese is strict about whose mind it is. "},{"t":"思","r":"おも"},{"t":"う"},{"t":" reports your own thought; for someone else you need "},{"t":"思","r":"おも"},{"t":"っている"},{"t":", because you can only observe another person thinking, not do it."}]'::jsonb),
  ('ed87973724059ee60e1736529bd4186941ad3766882cb94b4d813e394f64883a', '日本語が話せるようになりました, "I have got to where I can speak Japanese".', '[{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"話","r":"わ"},{"t":"せるようになりました"},{"t":", \"I have got to where I can speak Japanese\"."}]'::jsonb),
  ('48c8006678c5ad27f5205ee0e069fd57defb7b4c3523a4f8720e59cb9fdfff36', '弟は行きたがっている. 寒がる, 怖がる.', '[{"t":"弟","r":"おとと"},{"t":"は"},{"t":"行","r":"い"},{"t":"きたがっている"},{"t":". "},{"t":"寒","r":"さむ"},{"t":"がる"},{"t":", "},{"t":"怖","r":"こわ"},{"t":"がる"},{"t":"."}]'::jsonb),
  ('006bc182145673b2d756d6eb4ba9f0d60e2ca63ebfd57067d1123284fbaf5a0d', '高いけれど、買います. けれども is the fullest form, けど the most casual.', '[{"t":"高","r":"たか"},{"t":"いけれど"},{"t":"、"},{"t":"買","r":"か"},{"t":"います"},{"t":". "},{"t":"けれども"},{"t":" is the fullest form, "},{"t":"けど"},{"t":" the most casual."}]'::jsonb),
  ('85664e26c15107c2472968dd474b16d8c9fbe4deb2df544927ff79b73160f230', '行くな, "don''t go".', '[{"t":"行","r":"い"},{"t":"くな"},{"t":", \"don''t go\"."}]'::jsonb),
  ('a0321315296e2b9938a9c144cebc554eaafb5e33da834f328f5a74d26256f620', 'Not to be confused with the softening な of 食べな, which is a clipped 食べなさい and means the opposite. The verb form separates them: plain present + な forbids, stem + な urges.', '[{"t":"Not to be confused with the softening "},{"t":"な"},{"t":" of "},{"t":"食","r":"た"},{"t":"べな"},{"t":", which is a clipped "},{"t":"食","r":"た"},{"t":"べなさい"},{"t":" and means the opposite. The verb form separates them: plain present + "},{"t":"な"},{"t":" forbids, stem + "},{"t":"な"},{"t":" urges."}]'::jsonb),
  ('70ffaabd1c7b6005821d0a408c7da12a22876cd768cc13b9b61650771bd2bc20', '〜前に / 〜後で', '[{"t":"〜"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" / 〜"},{"t":"後","r":"あと"},{"t":"で"}]'::jsonb),
  ('92ffc0e09891280a0661c6778f7e810af199df8b03bcc854a8a1d28e237cc06e', 'Plain present + 前に / Verb-た + 後で', '[{"t":"Plain present + "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" / Verb-"},{"t":"た"},{"t":" + "},{"t":"後","r":"あと"},{"t":"で"}]'::jsonb),
  ('c62131679c57922cf4089ef3d4014d870fdc8617805939564da8498bd2504bf8', '食べる前に手を洗います. 食べた後で歯を磨きます.', '[{"t":"食","r":"た"},{"t":"べる"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":"手","r":"て"},{"t":"を"},{"t":"洗","r":"あら"},{"t":"います"},{"t":". "},{"t":"食","r":"た"},{"t":"べた"},{"t":"後","r":"あと"},{"t":"で"},{"t":"歯","r":"し"},{"t":"を"},{"t":"磨","r":"みが"},{"t":"きます"},{"t":"."}]'::jsonb),
  ('73068678d66b7a7dbd7209530b5e7a4e2343b9c3584be261778cd1eaf9ce416a', 'The tense is fixed by the pattern, not by the sentence: 前に always takes the plain present and 後で always takes た, however long ago it all happened.', '[{"t":"The tense is fixed by the pattern, not by the sentence: "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" always takes the plain present and "},{"t":"後","r":"あと"},{"t":"で"},{"t":" always takes "},{"t":"た"},{"t":", however long ago it all happened."}]'::jsonb),
  ('74793f2c7dc9c5e0577155489931f3bcf327c1408632efe9b03d4db26bebbc3e', '行かなくてもいいです.', '[{"t":"行","r":"い"},{"t":"かなくてもいいです"},{"t":"."}]'::jsonb),
  ('430ec20792b21a84156057ccdc2c3a6455e6bf6d09a7e202fa9a7015ab0d75e0', 'お持ちします, "let me carry that". Dedicated forms: 言う → 申す, 行く → 参る.', '[{"t":"お"},{"t":"持","r":"も"},{"t":"ちします"},{"t":", \"let me carry that\". Dedicated forms: "},{"t":"言","r":"い"},{"t":"う"},{"t":" → "},{"t":"申","r":"もう"},{"t":"す"},{"t":", "},{"t":"行","r":"い"},{"t":"く"},{"t":" → "},{"t":"参","r":"まい"},{"t":"る"},{"t":"."}]'::jsonb),
  ('b17d8be27c06ff75a31a3abbd97b0482faa66c7cba8786f387194fc0ee5eebc8', '雨が降っても行きます. Adjectives: 高くても. Nouns: 学生でも.', '[{"t":"雨","r":"あめ"},{"t":"が"},{"t":"降","r":"お"},{"t":"っても"},{"t":"行","r":"い"},{"t":"きます"},{"t":". Adjectives: "},{"t":"高","r":"たか"},{"t":"くても"},{"t":". Nouns: "},{"t":"学生","r":"がくせい"},{"t":"でも"},{"t":"."}]'::jsonb),
  ('578e58fe2c3e054ceb5fed781b3a3bde38c07a453010e1bfa869309813880537', '食べるところ (about to), 食べているところ (mid-way), 食べたところ (just done).', '[{"t":"食","r":"た"},{"t":"べるところ"},{"t":" (about to), "},{"t":"食","r":"た"},{"t":"べているところ"},{"t":" (mid-way), "},{"t":"食","r":"た"},{"t":"べたところ"},{"t":" (just done)."}]'::jsonb),
  ('f91f7f456bfa5693194029c317a5e24b9fe0fca1b58711c76e7f8f26a56005c0', '〜場合', '[{"t":"〜"},{"t":"場合","r":"ばやい"}]'::jsonb),
  ('d3351bb8987acde799dde7a6700eabbd32ade6519a73b8f2d08589e8b279f099', 'Plain form / Noun の + 場合', '[{"t":"Plain form / Noun "},{"t":"の"},{"t":" + "},{"t":"場合","r":"ばやい"}]'::jsonb),
