  ('1f21559ec9d4a933c34f28351334f941dd16b29db3ae92961ffd62105696cb93', '同じ + Noun', '[{"t":"同","r":"おな"},{"t":"じ"},{"t":" + Noun"}]'::jsonb),
  ('af5aa084f6511c403ee0cb1c61e8f3cfa87979c17faddd24d5cbdd50e9ce765f', '同じ本を読みました. AとBは同じです.', '[{"t":"同","r":"おな"},{"t":"じ"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みました"},{"t":". A"},{"t":"と"},{"t":"B"},{"t":"は"},{"t":"同","r":"おな"},{"t":"じです"},{"t":"."}]'::jsonb),
