  ('de16c3ca3550c0457cd3f7953ac46163b570d4cd894be7dcb4a964666b525935', '日本語が分かります. 料理ができます.', '[{"t":"日本語","r":"にほんご"},{"t":"が"},{"t":"分","r":"わ"},{"t":"かります"},{"t":". "},{"t":"料理","r":"りょうり"},{"t":"ができます"},{"t":"."}]'::jsonb),
  ('aadea21850bb85e00f22a88b0a7c79a555426b1664068d6a935f9230e6461e75', 'Both are intransitive and take が. 分かる is closer to "becomes clear to me" than to "I understand", which is why the grammar puts the thing in the subject.', '[{"t":"Both are intransitive and take "},{"t":"が"},{"t":". "},{"t":"分","r":"わ"},{"t":"かる"},{"t":" is closer to \"becomes clear to me\" than to \"I understand\", which is why the grammar puts the thing in the subject."}]'::jsonb),
