  ('c96009dedafe01df984c2903f935345dcb398c013636d805874354944ce0b96d', 'Number + 本', '[{"t":"Number + "},{"t":"本","r":"ほん"}]'::jsonb),
  ('e46291fec55ba84c6bb6065bbb42321494e3df17f5e5d7241a3584007ff83886', 'ペンを二本. Bottles, pens, umbrellas, trees.', '[{"t":"ペンを"},{"t":"二","r":"りゃん"},{"t":"本","r":"ほん"},{"t":". Bottles, pens, umbrellas, trees."}]'::jsonb),
