  ('5f3e3869cccb72bbbe758da633a75fed0b12760e0c0c72390c1358dd53d9703b', '二十歳 is irregular: はたち.', '[{"t":"二十歳","r":"はたち"},{"t":" is irregular: "},{"t":"はたち"},{"t":"."}]'::jsonb),
  ('bd560aa3bcc152871c2a68bad8b8229f044a71a26ed7743232b22e6a32043cc8', '学生でした. Negative: じゃありませんでした.', '[{"t":"学生","r":"がくせい"},{"t":"でした"},{"t":". Negative: "},{"t":"じゃありませんでした"},{"t":"."}]'::jsonb),
