  ('fc5c3092fc5096955c642318d120af6a228017beef3041058a95217b2ffe560f', '毎日走っています. 銀行で働いています.', '[{"t":"毎日","r":"まいにち"},{"t":"走","r":"はし"},{"t":"っています"},{"t":". "},{"t":"銀行","r":"ぎんこう"},{"t":"で"},{"t":"働","r":"はたら"},{"t":"いています"},{"t":"."}]'::jsonb),
  ('248b8235a6b3dd9213561cdabaf080227d9fa5f1438cc8409c109be03ad3934f', '早い → 早く歩く. 静か → 静かに歩く.', '[{"t":"早","r":"はや"},{"t":"い"},{"t":" → "},{"t":"早","r":"はや"},{"t":"く"},{"t":"歩","r":"ある"},{"t":"く"},{"t":". "},{"t":"静","r":"しず"},{"t":"か"},{"t":" → "},{"t":"静","r":"しず"},{"t":"かに"},{"t":"歩","r":"ある"},{"t":"く"},{"t":"."}]'::jsonb),
  ('89a3c9a1e28018a80e0f291a4dc939a70c181f22c4ac27271a90676921e7d70e', '何か / だれか / どこか', '[{"t":"何","r":"なに"},{"t":"か"},{"t":" / "},{"t":"だれか"},{"t":" / "},{"t":"どこか"}]'::jsonb),
  ('c3562aa40f41e4cf2d9d3bb8e7ab68fe3b82c19a80209e003149881e0daa6dde', '何か食べましたか. だれかいますか.', '[{"t":"何","r":"なに"},{"t":"か"},{"t":"食","r":"た"},{"t":"べましたか"},{"t":". "},{"t":"だれかいますか"},{"t":"."}]'::jsonb),
  ('03778b365f0bef2de1290ee69c6056bbd8d7d8688708c98772df851df2edfbc9', 'The particle after them is usually dropped: 何か食べる, not 何かを食べる.', '[{"t":"The particle after them is usually dropped: "},{"t":"何","r":"なに"},{"t":"か"},{"t":"食","r":"た"},{"t":"べる"},{"t":", not "},{"t":"何","r":"なに"},{"t":"かを"},{"t":"食","r":"た"},{"t":"べる"},{"t":"."}]'::jsonb),
  ('f2f5331366cdc942f281216c4efd9f452cb70640e09bf86db1d21fe45d6f87cf', 'Verb stem + に + 行く / 来る', '[{"t":"Verb stem + "},{"t":"に"},{"t":" + "},{"t":"行","r":"い"},{"t":"く"},{"t":" / "},{"t":"来","r":"く"},{"t":"る"}]'::jsonb),
  ('23525312675e8e78cb0ba2ee8c3e7a30fe7d194fc20821b4d09c348d5818aef1', '映画を見に行きます. 昼ごはんを食べに来ました.', '[{"t":"映画","r":"えいが"},{"t":"を"},{"t":"見","r":"み"},{"t":"に"},{"t":"行","r":"い"},{"t":"きます"},{"t":". "},{"t":"昼","r":"ひる"},{"t":"ごはんを"},{"t":"食","r":"た"},{"t":"べに"},{"t":"来","r":"らい"},{"t":"ました"},{"t":"."}]'::jsonb),
  ('bf8192eb07f69229c51dc7e0eab97a030b1748f5f74dc0cd8e434579c972666a', '頭が痛いんです. Nouns and な-adjectives take な: 学生なんです.', '[{"t":"頭","r":"とう"},{"t":"が"},{"t":"痛","r":"いた"},{"t":"いんです"},{"t":". Nouns and "},{"t":"な"},{"t":"-adjectives take "},{"t":"な"},{"t":": "},{"t":"学生","r":"がくせい"},{"t":"なんです"},{"t":"."}]'::jsonb),
  ('03b6cb7736afca91a6ec409363f6c5d8c267bfe6814a6000029fcdca7bb8981d', 'It frames a statement as a reason or background rather than a bare fact. 行きます states a plan; 行くんです answers a question nobody has quite asked.', '[{"t":"It frames a statement as a reason or background rather than a bare fact. "},{"t":"行","r":"い"},{"t":"きます"},{"t":" states a plan; "},{"t":"行","r":"い"},{"t":"くんです"},{"t":" answers a question nobody has quite asked."}]'::jsonb),
  ('3c067ead686334bf932ca01c62212cd5401befab39bf5ae70b138f93eef57c2b', '私は明日図書館で本を読みます.', '[{"t":"私","r":"わちき"},{"t":"は"},{"t":"明日","r":"あした"},{"t":"図書館","r":"としょかん"},{"t":"で"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みます"},{"t":"."}]'::jsonb),
  ('88bfd6e0023acdc091f9c88dc0173a0ed03437e4ef433cf8bac230b04eda4d8d', '朝ごはんを食べないで学校に行きました.', '[{"t":"朝","r":"あさ"},{"t":"ごはんを"},{"t":"食","r":"た"},{"t":"べないで"},{"t":"学校","r":"がっこう"},{"t":"に"},{"t":"行","r":"い"},{"t":"きました"},{"t":"."}]'::jsonb),
  ('dc34bf83b86041ae92e4c1dbb90d256dff0650b610fc5edeb22fab744fd47fec', 'Distinct from 〜なくて, which gives a reason: 分からなくて困った is "I was stuck because I didn''t understand".', '[{"t":"Distinct from 〜"},{"t":"なくて"},{"t":", which gives a reason: "},{"t":"分","r":"わ"},{"t":"からなくて"},{"t":"困","r":"こま"},{"t":"った"},{"t":" is \"I was stuck because I didn''t understand\"."}]'::jsonb),
  ('de4eea9c72b2d8e5d43a7a7b09331dd0dfcf9cb3815322af95b16ebf86826002', '（私は）学生です. 「食べましたか」「はい、食べました」', '[{"t":"（"},{"t":"私","r":"わちき"},{"t":"は"},{"t":"）"},{"t":"学生","r":"がくせい"},{"t":"です"},{"t":". 「"},{"t":"食","r":"た"},{"t":"べましたか"},{"t":"」「"},{"t":"はい"},{"t":"、"},{"t":"食","r":"た"},{"t":"べました"},{"t":"」"}]'::jsonb),
  ('fd184fd13f5f19be170b2990638e598b9f2208f694ee2445b232327fc7008582', 'Not laziness but the norm: repeating 私は every sentence sounds insistent, as if contrasting yourself with someone else.', '[{"t":"Not laziness but the norm: repeating "},{"t":"私","r":"わちき"},{"t":"は"},{"t":" every sentence sounds insistent, as if contrasting yourself with someone else."}]'::jsonb),
  ('7aeab24388dd797465289627e3ce6e0c882fdafaf16c24248863756df9d8a535', '食べる → 食べない, 行く → 行かない, する → しない, 来る → 来ない. ある is irregular: its negative is ない. Conjugates like an i-adjective: 食べなかった, 食べなくて.', '[{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べない"},{"t":", "},{"t":"行","r":"い"},{"t":"く"},{"t":" → "},{"t":"行","r":"い"},{"t":"かない"},{"t":", "},{"t":"する"},{"t":" → "},{"t":"しない"},{"t":", "},{"t":"来","r":"く"},{"t":"る"},{"t":" → "},{"t":"来","r":"らい"},{"t":"ない"},{"t":". "},{"t":"ある"},{"t":" is irregular: its negative is "},{"t":"ない"},{"t":". Conjugates like an i-adjective: "},{"t":"食","r":"た"},{"t":"べなかった"},{"t":", "},{"t":"食","r":"た"},{"t":"べなくて"},{"t":"."}]'::jsonb),
  ('79ff332115ed628f2e695367601e3958a50f8da01d8aa4ee44afdf1a6ff949c6', 'Formed exactly like the て-form but ending in た/だ: 食べて → 食べた, 飲んで → 飲んだ. The polite equivalent is ました.', '[{"t":"Formed exactly like the "},{"t":"て"},{"t":"-form but ending in "},{"t":"た"},{"t":"/"},{"t":"だ"},{"t":": "},{"t":"食","r":"た"},{"t":"べて"},{"t":" → "},{"t":"食","r":"た"},{"t":"べた"},{"t":", "},{"t":"飲","r":"の"},{"t":"んで"},{"t":" → "},{"t":"飲","r":"の"},{"t":"んだ"},{"t":". The polite equivalent is "},{"t":"ました"},{"t":"."}]'::jsonb),
  ('4d341b96161623ab992e0df43fb6a75df17b9d3877778b2db650ba064bc968d1', 'た is not purely past. In 分かった ("I''ve got it") or あった ("there it is") it marks a state just reached, which is closer to a perfect than a simple past.', '[{"t":"た"},{"t":" is not purely past. In "},{"t":"分","r":"わ"},{"t":"かった"},{"t":" (\"I''ve got it\") or "},{"t":"あった"},{"t":" (\"there it is\") it marks a state just reached, which is closer to a perfect than a simple past."}]'::jsonb),
  ('b20122f66c4555a8ffa65b4bafd1e1ae0d8b0a84a568c176dae0bf9760a4cc97', '肉も魚も好きです. 肉も魚も食べません.', '[{"t":"肉","r":"にく"},{"t":"も"},{"t":"魚","r":"さかな"},{"t":"も"},{"t":"好","r":"ず"},{"t":"きです"},{"t":". "},{"t":"肉","r":"にく"},{"t":"も"},{"t":"魚","r":"さかな"},{"t":"も"},{"t":"食","r":"た"},{"t":"べません"},{"t":"."}]'::jsonb),
  ('8b48ee4554a8a7e5c1095f3018a6405734fccec4e9a225afcdac6b1f39e1ab20', 'The て-form joins actions ("and then"), and is the required base for ている, てください, てもいい and many more. Formation depends on the verb ending: 食べる → 食べて, 書く → 書いて, 泳ぐ → 泳いで, 飲む → 飲んで, 行く → 行って (irregular).', '[{"t":"The "},{"t":"て"},{"t":"-form joins actions (\"and then\"), and is the required base for "},{"t":"ている"},{"t":", "},{"t":"てください"},{"t":", "},{"t":"てもいい"},{"t":" and many more. Formation depends on the verb ending: "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べて"},{"t":", "},{"t":"書","r":"か"},{"t":"く"},{"t":" → "},{"t":"書","r":"か"},{"t":"いて"},{"t":", "},{"t":"泳","r":"およ"},{"t":"ぐ"},{"t":" → "},{"t":"泳","r":"およ"},{"t":"いで"},{"t":", "},{"t":"飲","r":"の"},{"t":"む"},{"t":" → "},{"t":"飲","r":"の"},{"t":"んで"},{"t":", "},{"t":"行","r":"い"},{"t":"く"},{"t":" → "},{"t":"行","r":"い"},{"t":"って"},{"t":" (irregular)."}]'::jsonb),
  ('c82f0dd502ebfc5c2c9cd3e6affdf7d1e1e0f09a1a42afe4d39c397db482d504', 'が identifies who or what performs an action or holds a state, and typically introduces something new. It is required with 好き, 上手, ある/いる and question words: 誰が来ましたか。', '[{"t":"が"},{"t":" identifies who or what performs an action or holds a state, and typically introduces something new. It is required with "},{"t":"好","r":"ず"},{"t":"き"},{"t":", "},{"t":"上手","r":"じょうず"},{"t":", "},{"t":"ある"},{"t":"/"},{"t":"いる"},{"t":" and question words: "},{"t":"誰","r":"だれ"},{"t":"が"},{"t":"来","r":"らい"},{"t":"ましたか"},{"t":"。"}]'::jsonb),
  ('b0277e65261d44ae1798c595fdc2908be9bf9461c1021372f79481bef25ba1be', 'Question words take が, never は: 誰が? asks which person, and you cannot topicalise something you are asking about.', '[{"t":"Question words take "},{"t":"が"},{"t":", never "},{"t":"は"},{"t":": "},{"t":"誰","r":"だれ"},{"t":"が"},{"t":"? asks which person, and you cannot topicalise something you are asking about."}]'::jsonb),
  ('00f0879d0b0e07805d5da440a00323bccd5fad1305a26aaa03aecab7b00d1519', '学校に行く (destination), 七時に起きる (time), 友だちに話す (indirect object), 東京にいる (location of existence).', '[{"t":"学校","r":"がっこう"},{"t":"に"},{"t":"行","r":"い"},{"t":"く"},{"t":" (destination), "},{"t":"七","r":"しち"},{"t":"時","r":"とき"},{"t":"に"},{"t":"起","r":"お"},{"t":"きる"},{"t":" (time), "},{"t":"友","r":"ゆう"},{"t":"だちに"},{"t":"話","r":"はな"},{"t":"す"},{"t":" (indirect object), "},{"t":"東","r":"とん"},{"t":"京にいる"},{"t":" (location of existence)."}]'::jsonb),
  ('1844e41c06e83f59cf34252cb4d271e21267827a86bce0f6322e521314d0c607', 'に with a destination emphasises arrival; へ emphasises the direction travelled. For times, に is used with specific clock times and dates, but not with 今日, 明日 or 毎日.', '[{"t":"に"},{"t":" with a destination emphasises arrival; "},{"t":"へ"},{"t":" emphasises the direction travelled. For times, "},{"t":"に"},{"t":" is used with specific clock times and dates, but not with "},{"t":"今日","r":"きょう"},{"t":", "},{"t":"明日","r":"あした"},{"t":" or "},{"t":"毎日","r":"まいにち"},{"t":"."}]'::jsonb),
  ('9666b75f17624377e943eb5da518915aa12d3970ef36df9db42bb5a3d78e1d6d', 'ごはんを食べる "eat rice". Also marks the path traversed: 公園を歩く "walk through the park", 橋を渡る "cross the bridge".', '[{"t":"ごはんを"},{"t":"食","r":"た"},{"t":"べる"},{"t":" \"eat rice\". Also marks the path traversed: "},{"t":"公園","r":"こうえん"},{"t":"を"},{"t":"歩","r":"ある"},{"t":"く"},{"t":" \"walk through the park\", "},{"t":"橋","r":"はし"},{"t":"を"},{"t":"渡","r":"わた"},{"t":"る"},{"t":" \"cross the bridge\"."}]'::jsonb),
  ('7d73d7ce3fbb9f1352d36750b7db6c077b001ec50cedcd2db271bb949d463466', '電車はバスより速いです "the train is faster than the bus".', '[{"t":"電車","r":"でんしゃ"},{"t":"はバスより速いです"},{"t":" \"the train is faster than the bus\"."}]'::jsonb),
  ('6c70335f5250730570a4b6cb886cba0fbb2af243d2203ae3b3831bb48b5bab03', 'It replaces は, が and を rather than stacking with them: 私も学生です, never 私はも.', '[{"t":"It replaces "},{"t":"は"},{"t":", "},{"t":"が"},{"t":" and "},{"t":"を"},{"t":" rather than stacking with them: "},{"t":"私","r":"わちき"},{"t":"も"},{"t":"学生","r":"がくせい"},{"t":"です"},{"t":", never "},{"t":"私","r":"わちき"},{"t":"はも"},{"t":"."}]'::jsonb),
  ('c7cced5962bb01d992765d51f273ccf325703e34f05b49a514e595c192485d96', 'With a question word it means "any / none": 何もない "there is nothing", 誰も来ない "nobody comes".', '[{"t":"With a question word it means \"any / none\": "},{"t":"何","r":"なに"},{"t":"もない"},{"t":" \"there is nothing\", "},{"t":"誰","r":"だれ"},{"t":"も"},{"t":"来","r":"らい"},{"t":"ない"},{"t":" \"nobody comes\"."}]'::jsonb),
  ('923ff8a7106d00da1fdb1ed027488d1bd23d5a7167ac56460d7b93c198c08b62', '公園で遊びます "play in the park". Contrast に, which marks where something exists or is going: 公園にいます "am in the park".', '[{"t":"公園","r":"こうえん"},{"t":"で"},{"t":"遊","r":"あそ"},{"t":"びます"},{"t":" \"play in the park\". Contrast "},{"t":"に"},{"t":", which marks where something exists or is going: "},{"t":"公園","r":"こうえん"},{"t":"にいます"},{"t":" \"am in the park\"."}]'::jsonb),
  ('5868d19f58578fbe1a701e4542c5880b570fd33572a83ac6c48db481381b7f66', '本やノートがあります "there are books and notebooks, among other things". Often closes with など.', '[{"t":"本","r":"ほん"},{"t":"やノートがあります"},{"t":" \"there are books and notebooks, among other things\". Often closes with "},{"t":"など"},{"t":"."}]'::jsonb),
  ('e7b91096f561de1b581e50a974ed6d7a92ddf2009e11a2d9c6a5f0a663f17837', '高いですが、おいしいです "it is expensive, but tasty".', '[{"t":"高","r":"たか"},{"t":"いですが"},{"t":"、"},{"t":"おいしいです"},{"t":" \"it is expensive, but tasty\"."}]'::jsonb),
  ('dd6113a29c1fe12e5c982011690a445fdba1ba0b482c20bb5360bd462998fc69', '行きたいけど、時間がない "I want to go, but I have no time". けれど and けれども are progressively more formal.', '[{"t":"行","r":"い"},{"t":"きたいけど"},{"t":"、"},{"t":"時間","r":"じかん"},{"t":"がない"},{"t":" \"I want to go, but I have no time\". "},{"t":"けれど"},{"t":" and "},{"t":"けれども"},{"t":" are progressively more formal."}]'::jsonb),
