  ('811ff1ec2809a41418a26215156de5584b194b4af2de55972c0a840c44e29238', '〜前に', '[{"t":"〜"},{"t":"前","r":"ぜん"},{"t":"に"}]'::jsonb),
  ('bd031c158cd906e2f75302d1a501aa35283978d993e20c2ad8aee265cba0562b', 'Verb (dictionary) + 前に', '[{"t":"Verb (dictionary) + "},{"t":"前","r":"ぜん"},{"t":"に"}]'::jsonb),
  ('03cc5f447340493c76a0fd2b5a0557764c793786c5eabe8dcd65aa4de861d80f', '寝る前に本を読みます "I read before sleeping". With a noun: 食事の前に.', '[{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":"本","r":"ほん"},{"t":"を"},{"t":"読","r":"よ"},{"t":"みます"},{"t":" \"I read before sleeping\". With a noun: "},{"t":"食事","r":"しょくじ"},{"t":"の"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":"."}]'::jsonb),
  ('da3bbdd59f392454086ee8a4938077e1d81fb6647b63922c13ab19cbefa3f446', 'Always the DICTIONARY form, even when the sentence is past: 寝る前に読みました. The 前に fixes the order, so the verb needs no tense of its own.', '[{"t":"Always the DICTIONARY form, even when the sentence is past: "},{"t":"寝","r":"ね"},{"t":"る"},{"t":"前","r":"ぜん"},{"t":"に"},{"t":"読","r":"よ"},{"t":"みました"},{"t":". The "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" fixes the order, so the verb needs no tense of its own."}]'::jsonb),
  ('d4ff93ebe77fc0bf0ee03f44c8870bb46a3333d8927f95d1ba47fe8b479d1c22', '〜後で', '[{"t":"〜"},{"t":"後","r":"あと"},{"t":"で"}]'::jsonb),
