  ('e0ca563a56e2faa4265b23b09b08fce749ee52ac4e8808320e6939706fbb7405', '食べた後で出かけます "I will go out after eating".', '[{"t":"食","r":"た"},{"t":"べた"},{"t":"後","r":"あと"},{"t":"で"},{"t":"出","r":"で"},{"t":"かけます"},{"t":" \"I will go out after eating\"."}]'::jsonb),
  ('ff6f9f19fc3670e6e6f7b8e0f8c5f689fa239b7b0cfca8c3fe7454fecc85a82e', 'Mirror image of 前に: 後で takes the TA-form, 前に takes the dictionary form. The tense sits on whichever side has already happened.', '[{"t":"Mirror image of "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":": "},{"t":"後","r":"あと"},{"t":"で"},{"t":" takes the TA-form, "},{"t":"前","r":"ぜん"},{"t":"に"},{"t":" takes the dictionary form. The tense sits on whichever side has already happened."}]'::jsonb),
  ('19dbc975a26da9a51cae6cdc54921354f23ee87e3401691ed343afc359b2bbaa', '食べすぎました "I ate too much", 高すぎる "too expensive".', '[{"t":"食","r":"た"},{"t":"べすぎました"},{"t":" \"I ate too much\", "},{"t":"高","r":"たか"},{"t":"すぎる"},{"t":" \"too expensive\"."}]'::jsonb),
  ('5f462830105e855f5658bd06b7cab5efa1f0cb1441ae5294b51ea3a80e7fcca3', '先生になります "become a teacher", 寒くなりました "it has got cold".', '[{"t":"先生","r":"せんじょう"},{"t":"になります"},{"t":" \"become a teacher\", "},{"t":"寒","r":"さむ"},{"t":"くなりました"},{"t":" \"it has got cold\"."}]'::jsonb),
  ('fe60c788aae6f70dddd177c887870d616914d555bb4cfb60e2c9616306e23b58', 'Japanese prefers なる where English prefers "make": 便利になった "it became convenient" is far more natural than saying someone made it so. The change is described, not attributed.', '[{"t":"Japanese prefers "},{"t":"なる"},{"t":" where English prefers \"make\": "},{"t":"便利","r":"べんり"},{"t":"になった"},{"t":" \"it became convenient\" is far more natural than saying someone made it so. The change is described, not attributed."}]'::jsonb),
  ('433123229ff1dc816ee6932603de53dfa732fe5be0bc551fe0305aaf505fd6b2', '〜が好き', '[{"t":"〜"},{"t":"が"},{"t":"好","r":"ず"},{"t":"き"}]'::jsonb),
  ('88bde56479dd426c526042cb795f67e5df22c8844db36b04e561a457cc865c18', 'Noun + が + 好き', '[{"t":"Noun + "},{"t":"が"},{"t":" + "},{"t":"好","r":"ず"},{"t":"き"}]'::jsonb),
  ('5c8d6efaf3d10c98e0bddd3f10615a710264aff76084b666214a8e8fa9542d38', '音楽が好きです "I like music". Negative: 好きじゃありません.', '[{"t":"音楽","r":"おんがく"},{"t":"が"},{"t":"好","r":"ず"},{"t":"きです"},{"t":" \"I like music\". Negative: "},{"t":"好","r":"ず"},{"t":"きじゃありません"},{"t":"."}]'::jsonb),
  ('682eef52873733a3bf2e06ac47f68cfc39fcc11e824cada57bac79fa34fbe4e0', '好き is an adjective, not a verb, so the thing liked takes が rather than を. "I like it" is closer to "it is likeable to me".', '[{"t":"好","r":"ず"},{"t":"き"},{"t":" is an adjective, not a verb, so the thing liked takes "},{"t":"が"},{"t":" rather than "},{"t":"を"},{"t":". \"I like it\" is closer to \"it is likeable to me\"."}]'::jsonb),
  ('0335360529da3a840628df62fb37457aa49137a1aab28bf743342e900d1904f1', '一つだけください "just one, please".', '[{"t":"一","r":"ひと"},{"t":"つだけください"},{"t":" \"just one, please\"."}]'::jsonb),
