  ('aa066163a9c77a9670613fcc39e0c3cb36c66b05cdd3e8e2e8cf90729054ec66', 'Which reading you get depends on the verb, not on ている. This is the single most common source of confusion at N5: 知っている means "know", never "am knowing".', '[{"t":"Which reading you get depends on the verb, not on "},{"t":"ている"},{"t":". This is the single most common source of confusion at N5: "},{"t":"知","r":"し"},{"t":"っている"},{"t":" means \"know\", never \"am knowing\"."}]'::jsonb),
  ('7f0af136cb0e6c06bb720af7849e5bc313d213f67f3a3d3a9d9ad62e85e6855b', '高い → 高くない → 高かった → 高くなかった. They attach directly to a noun: 高い本.', '[{"t":"高","r":"たか"},{"t":"い"},{"t":" → "},{"t":"高","r":"たか"},{"t":"くない"},{"t":" → "},{"t":"高","r":"たか"},{"t":"かった"},{"t":" → "},{"t":"高","r":"たか"},{"t":"くなかった"},{"t":". They attach directly to a noun: "},{"t":"高","r":"たか"},{"t":"い"},{"t":"本","r":"ほん"},{"t":"."}]'::jsonb),
  ('eb564a92fdd62fd301eb9e8a8b7df8788099b0aaec194b10c138acf80dfbfd73', 'い-adjectives carry their own tense, so 高いでした is wrong; です adds politeness, never past. The adjective has already done that job.', '[{"t":"い"},{"t":"-adjectives carry their own tense, so "},{"t":"高","r":"たか"},{"t":"いでした"},{"t":" is wrong; "},{"t":"です"},{"t":" adds politeness, never past. The adjective has already done that job."}]'::jsonb),
  ('356d6953175b18843b030954c47f8d42fce34721e60fcfa3062018b6d10f4d08', 'The reason comes first: 高いから買いません "it''s expensive, so I won''t buy it". Works after plain or polite forms.', '[{"t":"The reason comes first: "},{"t":"高","r":"たか"},{"t":"いから"},{"t":"買","r":"か"},{"t":"いません"},{"t":" \"it''s expensive, so I won''t buy it\". Works after plain or polite forms."}]'::jsonb),
  ('e20a0179e099d16dfdb5eaaca837e5109b599aae5abbeabb5750bfe3baf3a503', '時間がないので、失礼します "as I have no time, I will excuse myself".', '[{"t":"時間","r":"じかん"},{"t":"がないので"},{"t":"、"},{"t":"失礼","r":"しつれい"},{"t":"します"},{"t":" \"as I have no time, I will excuse myself\"."}]'::jsonb),
  ('68477c20cb72f53f8af8fd1b89093fd7eb30f62c53c932abe99a36c76e5488ca', 'もうすぐ着きます. これから勉強します.', '[{"t":"もうすぐ"},{"t":"着","r":"き"},{"t":"きます"},{"t":". "},{"t":"これから"},{"t":"勉強","r":"べんきょう"},{"t":"します"},{"t":"."}]'::jsonb),
  ('c07a28f9ed6cd1148a260508108ca28e83b52fdc7a3f2b82ab5d8dc9801d3195', '日本語を勉強するために、日本に来ました. With a noun: 家族のために.', '[{"t":"日本語","r":"にほんご"},{"t":"を"},{"t":"勉強","r":"べんきょう"},{"t":"するために"},{"t":"、"},{"t":"日本","r":"にほん"},{"t":"に"},{"t":"来","r":"らい"},{"t":"ました"},{"t":". With a noun: "},{"t":"家族","r":"かぞく"},{"t":"のために"},{"t":"."}]'::jsonb),
  ('106e8a4867675213d7f4d8b0b2607d2e4b54bc4aac2f1db968f687d1f0b514ee', '友だちと行きます.', '[{"t":"友","r":"ゆう"},{"t":"だちと"},{"t":"行","r":"い"},{"t":"きます"},{"t":"."}]'::jsonb),
  ('02f7ba1fb20de3910f70ec5ed00cc84205c8b92f341b9fc1e176714cc2fe8186', 'いい天気ですね.', '[{"t":"いい"},{"t":"天気","r":"てんき"},{"t":"ですね"},{"t":"."}]'::jsonb),
  ('d3e93e8cae3d12a75c3144a3a09128721b4cf79964a57ab9d7704d05a85fd0b6', 'ね assumes the listener shares the view. Used about something only you could know (私は学生ですね), it sounds strange, because there is nothing to agree with.', '[{"t":"ね"},{"t":" assumes the listener shares the view. Used about something only you could know ("},{"t":"私","r":"わちき"},{"t":"は"},{"t":"学生","r":"がくせい"},{"t":"ですね"},{"t":"), it sounds strange, because there is nothing to agree with."}]'::jsonb),
  ('b6bec57c352495aa4da1f33b185335fc631e0cc0fd64c7b4525d493c8cc7d148', '泳ぐことが好きです. 彼が来るのを見ました.', '[{"t":"泳","r":"およ"},{"t":"ぐことが"},{"t":"好","r":"ず"},{"t":"きです"},{"t":". "},{"t":"彼","r":"かれ"},{"t":"が"},{"t":"来","r":"く"},{"t":"るのを"},{"t":"見","r":"み"},{"t":"ました"},{"t":"."}]'::jsonb),
  ('6904c61791d13c36cb03470a8b8526c468b586e399cad63e1b53526b834a0e3f', 'の is for something perceived directly: seeing, hearing, waiting. こと is for the abstract fact. 見る takes の because you watch an event, not a proposition.', '[{"t":"の"},{"t":" is for something perceived directly: seeing, hearing, waiting. "},{"t":"こと"},{"t":" is for the abstract fact. "},{"t":"見","r":"み"},{"t":"る"},{"t":" takes "},{"t":"の"},{"t":" because you watch an event, not a proposition."}]'::jsonb),
  ('b27865966139df2574959621efc62ac4fcd01d97b706bedad845321bc55a9938', '東京へ行きます "head toward Tokyo". Written へ, pronounced え.', '[{"t":"東","r":"とん"},{"t":"京へ"},{"t":"行","r":"い"},{"t":"きます"},{"t":" \"head toward Tokyo\". Written "},{"t":"へ"},{"t":", pronounced "},{"t":"え"},{"t":"."}]'::jsonb),
  ('0726814b010faa741e90f540dadfd623a7f5d8fd3dac561d8025b5bdee11a7a0', 'へ emphasises the heading; に emphasises arrival. 東京に行く says you got there, 東京へ行く says you set off that way, a difference English does not mark at all.', '[{"t":"へ"},{"t":" emphasises the heading; "},{"t":"に"},{"t":" emphasises arrival. "},{"t":"東","r":"とん"},{"t":"京に"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you got there, "},{"t":"東","r":"とん"},{"t":"京へ"},{"t":"行","r":"い"},{"t":"く"},{"t":" says you set off that way, a difference English does not mark at all."}]'::jsonb),
  ('697d37c44fed45c0cf1cbc5c9cfee54631ec7202a4ce7d1d3a97605c15e596df', '行きましょう "let''s go". With か it offers rather than proposes: 手伝いましょうか "shall I help?".', '[{"t":"行","r":"い"},{"t":"きましょう"},{"t":" \"let''s go\". With "},{"t":"か"},{"t":" it offers rather than proposes: "},{"t":"手伝","r":"てつだ"},{"t":"いましょうか"},{"t":" \"shall I help?\"."}]'::jsonb),
  ('2fc1d07cebc3f9217be58dcf49ddc42a3d1669065b81c0e31e13f17494dff507', 'ましょう assumes agreement. To ask whether someone wants to, use ませんか: 行きませんか is a genuine invitation, 行きましょう is closer to a decision.', '[{"t":"ましょう"},{"t":" assumes agreement. To ask whether someone wants to, use "},{"t":"ませんか"},{"t":": "},{"t":"行","r":"い"},{"t":"きませんか"},{"t":" is a genuine invitation, "},{"t":"行","r":"い"},{"t":"きましょう"},{"t":" is closer to a decision."}]'::jsonb),
  ('00aa97db6e7fe072fad1f81e1c9b16df2e466170ab78c05237d8de36cbf61bc9', '行きません, 食べません. The past is ませんでした.', '[{"t":"行","r":"い"},{"t":"きません"},{"t":", "},{"t":"食","r":"た"},{"t":"べません"},{"t":". The past is "},{"t":"ませんでした"},{"t":"."}]'::jsonb),
  ('bf0096dbaa19ca19118946d85aa7302f61026b6c5bd276173a9428361dbf5b54', 'ません is also how a polite invitation begins: 行きませんか is an offer, not a statement that you are not going.', '[{"t":"ません"},{"t":" is also how a polite invitation begins: "},{"t":"行","r":"い"},{"t":"きませんか"},{"t":" is an offer, not a statement that you are not going."}]'::jsonb),
  ('f59a7a65934099127e598267b81b73a705daa3add2b1bc2c069e01bb45d9f98d', '五時まで待ちます. 五時までに来てください.', '[{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"まで"},{"t":"待","r":"ま"},{"t":"ちます"},{"t":". "},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"までに"},{"t":"来","r":"らい"},{"t":"てください"},{"t":"."}]'::jsonb),
  ('e96d46379c95f599e51fc4e7244e0382e090a85ba0054ecb0179211e18e955c0', '九時から五時まで "from nine to five", 東京から大阪まで "from Tokyo to Osaka".', '[{"t":"九","r":"きゅう"},{"t":"時","r":"とき"},{"t":"から"},{"t":"五","r":"うー"},{"t":"時","r":"とき"},{"t":"まで"},{"t":" \"from nine to five\", "},{"t":"東","r":"とん"},{"t":"京から"},{"t":"大","r":"たい"},{"t":"阪まで"},{"t":" \"from Tokyo to Osaka\"."}]'::jsonb),
  ('742e08894e018d9d9c9877a2abd101f963ef143f599b080ec8c35dd44a77fc36', '〜向け / 〜向き', '[{"t":"〜"},{"t":"向","r":"む"},{"t":"け"},{"t":" / 〜"},{"t":"向","r":"む"},{"t":"き"}]'::jsonb),
  ('56915897728dff2702f5e9f4634fe07aefcee6000ed02a71d1826e8b49935a74', 'Noun + 向け', '[{"t":"Noun + "},{"t":"向","r":"む"},{"t":"け"}]'::jsonb),
  ('47dd2131397fec65dc5a3bc57af1a3c301c7af4d47c57f137c4252b627ab4889', '子ども向けの番組. 初心者向きの本.', '[{"t":"子","r":"こ"},{"t":"ども"},{"t":"向","r":"む"},{"t":"けの"},{"t":"番組","r":"ばんぐみ"},{"t":". "},{"t":"初","r":"うぶ"},{"t":"心","r":"しん"},{"t":"者","r":"しゃ"},{"t":"向","r":"む"},{"t":"きの"},{"t":"本","r":"ほん"},{"t":"."}]'::jsonb),
  ('5aaab4d33d725076cb955ccbb794bcae41b0bfeaa3e954d61c325e58ee6b8088', '向け is intent: it was made for them. 向き is fit: it happens to suit them. A textbook can be 子ども向け without being 子ども向き.', '[{"t":"向","r":"む"},{"t":"け"},{"t":" is intent: it was made for them. "},{"t":"向","r":"む"},{"t":"き"},{"t":" is fit: it happens to suit them. A textbook can be "},{"t":"子","r":"こ"},{"t":"ども"},{"t":"向","r":"む"},{"t":"け"},{"t":" without being "},{"t":"子","r":"こ"},{"t":"ども"},{"t":"向","r":"む"},{"t":"き"},{"t":"."}]'::jsonb),
  ('06e30d6deba89c8458f6d68adc2eaf42796cf398d286deb50dd5ffcaa7a2422c', '〜抜きに', '[{"t":"〜"},{"t":"抜","r":"ぬ"},{"t":"きに"}]'::jsonb),
  ('68cdf2ec589bc1db9ff565c42ace7a908fe266b627992bc53459b2e8d6df5a9e', 'Noun + 抜きに', '[{"t":"Noun + "},{"t":"抜","r":"ぬ"},{"t":"きに"}]'::jsonb),
  ('6bd17a74ed018fc00371a88ec061809ae713a2f1dd787ae61001b7a065a83649', '冗談抜きに、本気です. わさび抜きで.', '[{"t":"冗談","r":"じょうだん"},{"t":"抜","r":"ぬ"},{"t":"きに"},{"t":"、"},{"t":"本気","r":"ほんき"},{"t":"です"},{"t":". "},{"t":"わさび"},{"t":"抜","r":"ぬ"},{"t":"きで"},{"t":"."}]'::jsonb),
  ('303b13ff9a1340323b5302d187122586550b29c2752357248aba03ce17b486d0', '抜く is to pull out, so it removes something that would normally be included, which is why it works both for formalities and for wasabi.', '[{"t":"抜","r":"ぬ"},{"t":"く"},{"t":" is to pull out, so it removes something that would normally be included, which is why it works both for formalities and for wasabi."}]'::jsonb),
  ('6a6ec74417e4c625678d750ca2f2696cc8e38894ef27d44bdd5fa84adb2af83e', '電車のほうが速いです "the train is the faster one". Pairs with より: バスより電車のほうが速い.', '[{"t":"電車","r":"でんしゃ"},{"t":"のほうが速いです"},{"t":" \"the train is the faster one\". Pairs with "},{"t":"より"},{"t":": "},{"t":"バスより"},{"t":"電車","r":"でんしゃ"},{"t":"のほうが速い"},{"t":"."}]'::jsonb),
  ('d5a5a8ff6767cc6082a48d528056adfa3107e4fd4ddaeaab71b15a9912ca9e67', '方 literally means "side" or "direction", so the phrase is "the train side is faster"; Japanese compares by pointing at a side rather than inflecting the adjective.', '[{"t":"方","r":"かた"},{"t":" literally means \"side\" or \"direction\", so the phrase is \"the train side is faster\"; Japanese compares by pointing at a side rather than inflecting the adjective."}]'::jsonb),
  ('67a86059e50ca8522be10bd8f46b90668a9cd33995e7f8aa9dda9996abc2d466', '五段 / 一段 / する・くる', '[{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":" / "},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":" / "},{"t":"する・くる"}]'::jsonb),
  ('9862aa6d81e177c776d916a8209d5fd53021dc4eaca6f10c14eedcb788d17bc3', 'Japanese verbs do not each have their own endings to memorise. There are three groups, and once you know which group a verb is in, every form follows.

**Ichidan (一段)**: the easy ones. The dictionary form ends in 〜いる or 〜える, and you conjugate by dropping る and adding the ending. 食べる → 食べます, 食べて, 食べた, 食べない. Nothing else changes.

**Godan (五段)**: everything else ending in う, く, ぐ, す, つ, ぬ, ぶ, む, る. The final syllable shifts across the five vowel rows, which is what 五段, "five steps", means. 書く → 書きます, 書いて, 書いた, 書かない. The consonant stays, the vowel moves.

**Irregular**: there are only two, する (to do) and くる (to come). They are irregular in every form, and you learn them as they arrive. する is worth extra attention because it is how Japanese turns almost any noun into a verb: 勉強 → 勉強する, 電話 → 電話する.

ある is a fourth footnote: a godan verb in every form except the negative, where it becomes ない rather than あらない.', '[{"t":"Japanese verbs do not each have their own endings to memorise. There are three groups, and once you know which group a verb is in, every form follows.\n\n**Ichidan ("},{"t":"一","r":"いっち"},{"t":"段","r":"だん"},{"t":")**: the easy ones. The dictionary form ends in 〜"},{"t":"いる"},{"t":" or 〜"},{"t":"える"},{"t":", and you conjugate by dropping "},{"t":"る"},{"t":" and adding the ending. "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べます"},{"t":", "},{"t":"食","r":"た"},{"t":"べて"},{"t":", "},{"t":"食","r":"た"},{"t":"べた"},{"t":", "},{"t":"食","r":"た"},{"t":"べない"},{"t":". Nothing else changes.\n\n**Godan ("},{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":")**: everything else ending in "},{"t":"う"},{"t":", "},{"t":"く"},{"t":", "},{"t":"ぐ"},{"t":", "},{"t":"す"},{"t":", "},{"t":"つ"},{"t":", "},{"t":"ぬ"},{"t":", "},{"t":"ぶ"},{"t":", "},{"t":"む"},{"t":", "},{"t":"る"},{"t":". The final syllable shifts across the five vowel rows, which is what "},{"t":"五","r":"うー"},{"t":"段","r":"だん"},{"t":", \"five steps\", means. "},{"t":"書","r":"か"},{"t":"く"},{"t":" → "},{"t":"書","r":"か"},{"t":"きます"},{"t":", "},{"t":"書","r":"か"},{"t":"いて"},{"t":", "},{"t":"書","r":"か"},{"t":"いた"},{"t":", "},{"t":"書","r":"か"},{"t":"かない"},{"t":". The consonant stays, the vowel moves.\n\n**Irregular**: there are only two, "},{"t":"する"},{"t":" (to do) and "},{"t":"くる"},{"t":" (to come). They are irregular in every form, and you learn them as they arrive. "},{"t":"する"},{"t":" is worth extra attention because it is how Japanese turns almost any noun into a verb: "},{"t":"勉強","r":"べんきょう"},{"t":" → "},{"t":"勉強","r":"べんきょう"},{"t":"する"},{"t":", "},{"t":"電話","r":"でんわ"},{"t":" → "},{"t":"電話","r":"でんわ"},{"t":"する"},{"t":".\n\n"},{"t":"ある"},{"t":" is a fourth footnote: a godan verb in every form except the negative, where it becomes "},{"t":"ない"},{"t":" rather than "},{"t":"あらない"},{"t":"."}]'::jsonb),
  ('157e40d47d371a88b93e4fd29e97ad52de6b08144a05362ed915738e78df6409', 'The trap is that 〜いる and 〜える do not guarantee ichidan. 帰る, 入る, 走る and 切る all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates 帰る wrongly at least once.', '[{"t":"The trap is that 〜"},{"t":"いる"},{"t":" and 〜"},{"t":"える"},{"t":" do not guarantee ichidan. "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":", "},{"t":"入","r":"い"},{"t":"る"},{"t":", "},{"t":"走","r":"はし"},{"t":"る"},{"t":" and "},{"t":"切","r":"き"},{"t":"る"},{"t":" all look ichidan and are godan. There is no rule that catches them; they are a short list you meet one at a time, and every learner conjugates "},{"t":"帰","r":"かえ"},{"t":"る"},{"t":" wrongly at least once."}]'::jsonb),
  ('8cbad68ac11c78f6ba08fc83220980718ba09e9b65581cb8fbc6b38956fdd34b', 'は sets what the sentence is about. It contrasts with が, which marks the grammatical subject and introduces new information. 私は学生です: "as for me, student".', '[{"t":"は"},{"t":" sets what the sentence is about. It contrasts with "},{"t":"が"},{"t":", which marks the grammatical subject and introduces new information. "},{"t":"私","r":"わちき"},{"t":"は"},{"t":"学生","r":"がくせい"},{"t":"です"},{"t":": \"as for me, student\"."}]'::jsonb),
  ('2d5ec35518191d5ae6d422a998651c9bc63e52a4d8cbbfd9845ee0d956963f7c', 'は is written with the hiragana は but pronounced わ. It also carries contrast: 肉は食べません implies "meat specifically, whatever else I might eat".', '[{"t":"は"},{"t":" is written with the hiragana "},{"t":"は"},{"t":" but pronounced "},{"t":"わ"},{"t":". It also carries contrast: "},{"t":"肉","r":"にく"},{"t":"は"},{"t":"食","r":"た"},{"t":"べません"},{"t":" implies \"meat specifically, whatever else I might eat\"."}]'::jsonb),
  ('a97859743a073da416b0a893acce579a92c6f4d34b51c4f86f14ab2530104c20', '一つ, 二つ … 十つ does not exist; ten is 十.', '[{"t":"一","r":"ひと"},{"t":"つ"},{"t":", "},{"t":"二","r":"ふた"},{"t":"つ"},{"t":" … "},{"t":"十","r":"しー"},{"t":"つ"},{"t":" does not exist; ten is "},{"t":"十","r":"しー"},{"t":"."}]'::jsonb),
  ('05426ab7423b4f8649a89ab9d211ee84499494d60295531e5f67cf332096dcb4', '本とノート "a book and a notebook", and nothing else. 友だちと行きます "go with a friend".', '[{"t":"本","r":"ほん"},{"t":"とノート"},{"t":" \"a book and a notebook\", and nothing else. "},{"t":"友","r":"ゆう"},{"t":"だちと"},{"t":"行","r":"い"},{"t":"きます"},{"t":" \"go with a friend\"."}]'::jsonb),
  ('0f00d5552b563e0cf188f8c85c4747b35cfb4c3c55b06dc40c913ce0fdd5ca94', '食べたい "I want to eat". Conjugates as an i-adjective: 食べたかった, 食べたくない. Only for your own desire; for a third party use 〜たがる.', '[{"t":"食","r":"た"},{"t":"べたい"},{"t":" \"I want to eat\". Conjugates as an i-adjective: "},{"t":"食","r":"た"},{"t":"べたかった"},{"t":", "},{"t":"食","r":"た"},{"t":"べたくない"},{"t":". Only for your own desire; for a third party use 〜"},{"t":"たがる"},{"t":"."}]'::jsonb),
  ('d40ee4683abd8ba8df4ab240ec66729e55fd277e0f762250dc0e46b3c111653e', 'The object may take が instead of を: 水が飲みたい is at least as natural as 水を飲みたい, because たい makes the sentence adjective-like.', '[{"t":"The object may take "},{"t":"が"},{"t":" instead of "},{"t":"を"},{"t":": "},{"t":"水","r":"みず"},{"t":"が"},{"t":"飲","r":"の"},{"t":"みたい"},{"t":" is at least as natural as "},{"t":"水","r":"みず"},{"t":"を"},{"t":"飲","r":"の"},{"t":"みたい"},{"t":", because "},{"t":"たい"},{"t":" makes the sentence adjective-like."}]'::jsonb),
  ('cf458f8d46345d06f20ebafeca23d5f79d90e362003f457a060c98ab3fe5e1cb', '食べてみてください. Written in kana, the 見 is no longer literal.', '[{"t":"食","r":"た"},{"t":"べてみてください"},{"t":". Written in kana, the "},{"t":"見","r":"み"},{"t":" is no longer literal."}]'::jsonb),
  ('9250b44b088b91127de86d11ffcd96744b92496bdc76b687d0ac964cfe828b66', '学生です。', '[{"t":"学生","r":"がくせい"},{"t":"です"},{"t":"。"}]'::jsonb),
  ('84127fe05697758fc9cade0a8294acdf996446b2f43ae804d8482d3194cb8a73', '静かです。', '[{"t":"静","r":"しず"},{"t":"かです"},{"t":"。"}]'::jsonb),
