  ('ac9b0fe5bec8cb8264342b8b162995d5cc14c73b1831cbebb137f3a70fe77ba7', '食べる → 食べ + ます / て / た / ない', '[{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べ"},{"t":" + "},{"t":"ます"},{"t":" / "},{"t":"て"},{"t":" / "},{"t":"た"},{"t":" / "},{"t":"ない"}]'::jsonb),
  ('db41fa5f23ec57d508f455db30665b1d3abe0739f360a61866b329c55aea2061', '書く → 書き / 書い / 書か', '[{"t":"書","r":"か"},{"t":"く"},{"t":" → "},{"t":"書","r":"か"},{"t":"き"},{"t":" / "},{"t":"書","r":"か"},{"t":"い"},{"t":" / "},{"t":"書","r":"か"},{"t":"か"}]'::jsonb),
  ('4ae9aa4f28dad4ac774dc95fdf2ee1b2ab761df41d197acfcb25c813b92ef5d2', '書く, 食べる, 話す, 待つ', '[{"t":"書","r":"か"},{"t":"く"},{"t":", "},{"t":"食","r":"た"},{"t":"べる"},{"t":", "},{"t":"話","r":"はな"},{"t":"す"},{"t":", "},{"t":"待","r":"ま"},{"t":"つ"}]'::jsonb),
  ('2adc0140940ca63b166f65cd2a5af0d8bdea4c8e4040ed39b3fd86ae0acd5990', '食べるます。', '[{"t":"食","r":"た"},{"t":"べるます"},{"t":"。"}]'::jsonb),
  ('56cc6bebb3d326ab4c9b128a1bf447c626d0141d2c89133dc6e444e828d1298d', '食べます。', '[{"t":"食","r":"た"},{"t":"べます"},{"t":"。"}]'::jsonb),
  ('45baa0ffa80d8880f901a68876652eb610c3887ac4dbbf3fb1a1f5df79d27e9b', 'Drop the final る (or shift the う-row) first: 食べる → 食べ + ます.', '[{"t":"Drop the final "},{"t":"る"},{"t":" (or shift the "},{"t":"う"},{"t":"-row) first: "},{"t":"食","r":"た"},{"t":"べる"},{"t":" → "},{"t":"食","r":"た"},{"t":"べ"},{"t":" + "},{"t":"ます"},{"t":"."}]'::jsonb),
  ('417239925ffe41757d2e75803c25568b83288d3a33625d11a9aaab4548ea6d4f', '行くて', '[{"t":"行","r":"い"},{"t":"くて"}]'::jsonb),
  ('fc3f37898b16faaa8000c1e8365f07d363d33253a7c23ba6958ffca38a89dbdb', '行って', '[{"t":"行","r":"い"},{"t":"って"}]'::jsonb),
  ('f7f99935254832c0d7f8383c2fb1a34367e3660e9597bcdddf1cb75cf4a6ef60', 'く-verbs take いて, but 行く is irregular.', '[{"t":"く"},{"t":"-verbs take "},{"t":"いて"},{"t":", but "},{"t":"行","r":"い"},{"t":"く"},{"t":" is irregular."}]'::jsonb),
  ('429039b189a70bd7d15dc7da70dd2d7f698a69416c903f1fa08d75dd1562cc36', '書く → 書いて follows the rule; 行く is the one exception and takes 行って.', '[{"t":"書","r":"か"},{"t":"く"},{"t":" → "},{"t":"書","r":"か"},{"t":"いて"},{"t":" follows the rule; "},{"t":"行","r":"い"},{"t":"く"},{"t":" is the one exception and takes "},{"t":"行","r":"い"},{"t":"って"},{"t":"."}]'::jsonb),
  ('353a9cdbf5476fe43bb8efdb91210b542a896b8f4307e9836e984b46f9d33ed8', '行いた', '[{"t":"行","r":"おこな"},{"t":"いた"}]'::jsonb),
  ('183576227b8b5fc2da436769e052c94684d37610a06f778c7f5f218a35dff521', '行った', '[{"t":"行","r":"い"},{"t":"った"}]'::jsonb),
  ('2992ac17b50cd5ce6e5d2a7bc8d214a8b184cb8a1dadcb0069326f5dcb235d05', 'If you know 行って, then 行った follows; the two forms always share their shape.', '[{"t":"If you know "},{"t":"行","r":"い"},{"t":"って"},{"t":", then "},{"t":"行","r":"い"},{"t":"った"},{"t":" follows; the two forms always share their shape."}]'::jsonb),
  ('4e09881e93608be974179182a0d58be9bb3ab315bcac29044ed4d895dba2dd99', '彼は死んでいます = He is dying.', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"死","r":"し"},{"t":"んでいます"},{"t":" = He is dying."}]'::jsonb),
  ('a039596d9c10c0e606f70f852a614773bfcece8fbde56d0ab79335af28dfdee9', '彼は死んでいます = He is dead.', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"死","r":"し"},{"t":"んでいます"},{"t":" = He is dead."}]'::jsonb),
  ('6d2afd044e83180aa3d26de8fb5650e476be71e43adf697eef8a81686bd9f221', '死ぬ is a change-of-state verb.', '[{"t":"死","r":"し"},{"t":"ぬ"},{"t":" is a change-of-state verb."}]'::jsonb),
