  ('0ac68856539074c4602bdb79fd0efab2b54a53a68ceaee3b8ea1e298aebba827', '私が学生です。(as a neutral self-introduction)', '[{"t":"私","r":"わちき"},{"t":"が"},{"t":"学生","r":"がくせい"},{"t":"です"},{"t":"。(as a neutral self-introduction)"}]'::jsonb),
  ('672ded26ea3a72ec940b8c07b3a20b4c3f2c4c84b17b7f253a96c435e7b02a3f', '私は学生です。', '[{"t":"私","r":"わちき"},{"t":"は"},{"t":"学生","r":"がくせい"},{"t":"です"},{"t":"。"}]'::jsonb),
  ('f461d6ad12a9f5ccc9e9d319d5225858f39717d59d7ff2c81ba98cbc2c00fa66', '誰は来ましたか。', '[{"t":"誰","r":"だれ"},{"t":"は"},{"t":"来","r":"らい"},{"t":"ましたか"},{"t":"。"}]'::jsonb),
  ('38208abf69c8222c6600ed0578632bbce9cf4cd4e977b984ab98d30c228ddfd3', '誰が来ましたか。', '[{"t":"誰","r":"だれ"},{"t":"が"},{"t":"来","r":"らい"},{"t":"ましたか"},{"t":"。"}]'::jsonb),
  ('e71640cb1c237b6d004a3140aeacd301e0b29fcb4f1df901ad06fb3545fc83f3', '見るください。', '[{"t":"見","r":"み"},{"t":"るください"},{"t":"。"}]'::jsonb),
  ('e947d6b17e05046218e79b077a4b434d84e3894d850d50cc7d4f7f6acbf8c1eb', '行くましょう。', '[{"t":"行","r":"い"},{"t":"くましょう"},{"t":"。"}]'::jsonb),
  ('1e58c593320d7bd12531d389072479d06da03d922bd5b19be0d28cbceb5499f8', 'ましょう is built on ます, so it takes the same stem: 行き + ましょう.', '[{"t":"ましょう"},{"t":" is built on "},{"t":"ます"},{"t":", so it takes the same stem: "},{"t":"行","r":"い"},{"t":"き"},{"t":" + "},{"t":"ましょう"},{"t":"."}]'::jsonb),
  ('27d4019302820c844c8f960444b8f479320fb93c7dcf4674385eee9dea98f263', '彼は行きたいです。', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"行","r":"い"},{"t":"きたいです"},{"t":"。"}]'::jsonb),
  ('7bf391782b830a0f5bb5b0b32c24dfff1d26030f99f1bca23ba032301fa568ef', '彼は行きたがっています。', '[{"t":"彼","r":"かれ"},{"t":"は"},{"t":"行","r":"い"},{"t":"きたがっています"},{"t":"。"}]'::jsonb),
  ('2ad695a039669dd94429b2caf8230cafad0d99e633e30a294c69ad38307a7dfa', '買いませんから高いです。', '[{"t":"買","r":"か"},{"t":"いませんから"},{"t":"高","r":"たか"},{"t":"いです"},{"t":"。"}]'::jsonb),
  ('62ce61541c8b1b5892f927e446fa7f8abff16ff88650497e537e5f08f4799ff1', '高いから買いません。', '[{"t":"高","r":"たか"},{"t":"いから"},{"t":"買","r":"か"},{"t":"いません"},{"t":"。"}]'::jsonb),
  ('5205ff64fa428eff4500610327f366d4addc8abdce309cd7abd861e3bfea6d30', '明日に行きます。', '[{"t":"明日","r":"あした"},{"t":"に"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('dfdec6f66498aeee4eeaf9dcbec03784eb88ffe3b67edd52ca4748f834d13c08', '明日行きます。', '[{"t":"明日","r":"あした"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('331a0bdd5a9ea6377060b462ccd7e4e31bbfce694909b6d8af117c44393918aa', '明日 and 今日 are already adverbial; only absolute times like 七時 or 月曜日 take に.', '[{"t":"明日","r":"あした"},{"t":" and "},{"t":"今日","r":"きょう"},{"t":" are already adverbial; only absolute times like "},{"t":"七","r":"しち"},{"t":"時","r":"とき"},{"t":" or "},{"t":"月曜日","r":"げつようび"},{"t":" take "},{"t":"に"},{"t":"."}]'::jsonb),
  ('f323ed4ded7d5f3c3f176e1aeb1c643d89ea2ec64fb1d5b6b8475133e88e5e6e', '公園に歩きます。', '[{"t":"公園","r":"こうえん"},{"t":"に"},{"t":"歩","r":"あゆ"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('92aa3eab0e31892fb1bf7f37ffaba4cc2d7482d2b578d394fa425dd77902b78c', '公園を歩きます。', '[{"t":"公園","r":"こうえん"},{"t":"を"},{"t":"歩","r":"あゆ"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('40dbb79ca058adea0f8fd493ea3bb956a16d0d9a109396e94afcce8ef279843a', '私はも行きます。', '[{"t":"私","r":"わちき"},{"t":"はも"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('5ae8b0c172ed6c44cb37470ec5b4bd5bf476dbbbecad697129a388bb0d276c8d', '私も行きます。', '[{"t":"私","r":"わちき"},{"t":"も"},{"t":"行","r":"い"},{"t":"きます"},{"t":"。"}]'::jsonb),
  ('fae9de1a9b220ca385631627eee7540ea1d8fc922e3225613cc3d461fb037c5e', '本の私', '[{"t":"本","r":"ほん"},{"t":"の"},{"t":"私","r":"わちき"}]'::jsonb),
  ('c0a19949cb22ee534ad5c190b3f5f37f8d612d545911d039ca2276039f78152d', 'ですかあなたは学生?', '[{"t":"ですかあなたは"},{"t":"学生","r":"がくせい"},{"t":"?"}]'::jsonb),
  ('4179fac96ff3476ca6616f0837148a0a03122a4a5819ed4c9208f091d8db4b33', 'あなたは学生ですか。', '[{"t":"あなたは"},{"t":"学生","r":"がくせい"},{"t":"ですか"},{"t":"。"}]'::jsonb),
  ('043ef199349ec587c9cdc5a5a77202c11c7e704d6f23efb5471eb3ee34abdf4e', '入るもいいですか。', '[{"t":"入","r":"い"},{"t":"るもいいですか"},{"t":"。"}]'::jsonb),
  ('0d2e2f134823f2c338ec5b92a4890c1c9b6f160a85bfaea06975c33f1da8e378', '行きなければなりません。', '[{"t":"行","r":"い"},{"t":"きなければなりません"},{"t":"。"}]'::jsonb),
  ('e250fbd1890a23d653bdef4880b58e0fc2c97f5caa17390887dd712104a0eed8', 'Take the negative stem 行か, not the ます-stem 行き.', '[{"t":"Take the negative stem "},{"t":"行","r":"い"},{"t":"か"},{"t":", not the "},{"t":"ます"},{"t":"-stem "},{"t":"行","r":"い"},{"t":"き"},{"t":"."}]'::jsonb),
  ('c8819ddcf5f44a9ee55754e7e6cd832c47ce6d4e3d59d7a46b32323704db8adb', '高いだ。', '[{"t":"高","r":"たか"},{"t":"いだ"},{"t":"。"}]'::jsonb),
  ('76d80d9971980503769c230727c9d252df46ad553a1905605c92ed42dd4457af', '高いです。', '[{"t":"高","r":"たか"},{"t":"いです"},{"t":"。"}]'::jsonb),
  ('4ff079d53b60ee45aa0fcc06158ce3a6f836e07a7fbac0d3ceeba3eab0027675', 'An i-adjective already carries the predicate, so です only adds politeness: 高いです, never 高いだ.', '[{"t":"An i-adjective already carries the predicate, so "},{"t":"です"},{"t":" only adds politeness: "},{"t":"高","r":"たか"},{"t":"いです"},{"t":", never "},{"t":"高","r":"たか"},{"t":"いだ"},{"t":"."}]'::jsonb),
  ('d49726c73beaa56a78c60b297e69371e5312f353cb468ad423dbd2f27007f4eb', '学生だです。', '[{"t":"学生","r":"がくせい"},{"t":"だです"},{"t":"。"}]'::jsonb),
  ('39ca50758936fedf96ab22933db393ff7c472fa94179a0af20ef0dc51c0b9497', 'The volitional む became う, and ます + う contracted to ましょう. The same む sits behind the plain volitional: 行こう is 行か + う from the same source.

So ましょう and 〜おう are not two separate endings. They are the polite and plain faces of one volitional marker, which is why they mean exactly the same thing at different registers.', '[{"t":"The volitional "},{"t":"む"},{"t":" became "},{"t":"う"},{"t":", and "},{"t":"ます"},{"t":" + "},{"t":"う"},{"t":" contracted to "},{"t":"ましょう"},{"t":". The same "},{"t":"む"},{"t":" sits behind the plain volitional: "},{"t":"行","r":"い"},{"t":"こう"},{"t":" is "},{"t":"行","r":"い"},{"t":"か"},{"t":" + "},{"t":"う"},{"t":" from the same source.\n\nSo "},{"t":"ましょう"},{"t":" and 〜"},{"t":"おう"},{"t":" are not two separate endings. They are the polite and plain faces of one volitional marker, which is why they mean exactly the same thing at different registers."}]'::jsonb),
  ('762005e977f6bf242b9fd1f5212dd282e8da3c86dfc1b3b7d3eec5df393a1d98', 'ください is the imperative of 下さる, "to give downward". Putting a ます stem inside the お〜 frame makes the request about the listener''s action rather than about a thing.

So お待ちください is "please do the waiting", one step politer than 待ってください because the honorific frame is doing work the te-form request cannot.', '[{"t":"ください"},{"t":" is the imperative of "},{"t":"下","r":"くだ"},{"t":"さる"},{"t":", \"to give downward\". Putting a "},{"t":"ます"},{"t":" stem inside the "},{"t":"お"},{"t":"〜 frame makes the request about the listener''s action rather than about a thing.\n\nSo "},{"t":"お"},{"t":"待","r":"ま"},{"t":"ちください"},{"t":" is \"please do the waiting\", one step politer than "},{"t":"待","r":"ま"},{"t":"ってください"},{"t":" because the honorific frame is doing work the te-form request cannot."}]'::jsonb),
  ('b9209e190231869f8325f97735229635488e7c025eb123dbc24b99cf05b70a58', 'から develops from the Old Japanese noun 柄 (kara) meaning origin or source.', '[{"t":"から"},{"t":" develops from the Old Japanese noun "},{"t":"柄","r":"え"},{"t":" (kara) meaning origin or source."}]'::jsonb),
  ('da5a61b184da7982aa0bd5834afb5af202ab1a09ffa8ff48f7d2f34392840f09', 'Since comparisons require a reference point you base your judgment on, the semantic root in to be based on directly explains why より marks the standard of comparison. When you say A より高い (taller than A), you are using A as the foundation from which the comparison is made.', '[{"t":"Since comparisons require a reference point you base your judgment on, the semantic root in to be based on directly explains why "},{"t":"より"},{"t":" marks the standard of comparison. When you say A "},{"t":"より"},{"t":"高","r":"たか"},{"t":"い"},{"t":" (taller than A), you are using A as the foundation from which the comparison is made."}]'::jsonb),
  ('3fb145e80f2a4aac184328a8019a8ef0fbee7a7885f37d207003053d5b258f57', 'ながら attaches to the 連用形 and originally marked a state persisting unchanged.', '[{"t":"ながら"},{"t":" attaches to the "},{"t":"連","r":"つ"},{"t":"用","r":"よう"},{"t":"形","r":"なり"},{"t":" and originally marked a state persisting unchanged."}]'::jsonb),
  ('d3d597d0564bfbb29dc8edbd117cfd1552be82623ce0f671d2ce8144a3987c0f', 'The older sense survives in fixed expressions like 昔ながら ("as it always was") and 涙ながらに ("in tears"), where ながら means "while remaining in that state" rather than "at the same time as".

That is the reason the ながら clause is the background one. It was never a way of saying two things happened together; it described the condition something was in while the real action took place.', '[{"t":"The older sense survives in fixed expressions like "},{"t":"昔","r":"むかし"},{"t":"ながら"},{"t":" (\"as it always was\") and "},{"t":"涙","r":"なみだ"},{"t":"ながらに"},{"t":" (\"in tears\"), where "},{"t":"ながら"},{"t":" means \"while remaining in that state\" rather than \"at the same time as\".\n\nThat is the reason the "},{"t":"ながら"},{"t":" clause is the background one. It was never a way of saying two things happened together; it described the condition something was in while the real action took place."}]'::jsonb),
  ('58053980a3e5750e337d46f155c81b2dc5c2e989b54dd18d134bf40257eec372', 'ようにする is the same 様 with する: making it the way where something happens.', '[{"t":"ようにする"},{"t":" is the same "},{"t":"様","r":"さま"},{"t":" with "},{"t":"する"},{"t":": making it the way where something happens."}]'::jsonb),
  ('704f39f8a9684142e23aa4a48b62ee9775d247e95a79a1875cbabe0f4eddd101', 'なる and する are the standard Japanese pair for a change that happens and a change you bring about, and they sit either side of the identical ように.

So 早く寝るようにする is not a decision to sleep early; it is arranging matters so that early sleeping is what happens. The habitual, effortful reading that textbooks list separately is simply what "make it be that way" means when it is said about your own conduct.', '[{"t":"なる"},{"t":" and "},{"t":"する"},{"t":" are the standard Japanese pair for a change that happens and a change you bring about, and they sit either side of the identical "},{"t":"ように"},{"t":".\n\nSo "},{"t":"早","r":"はや"},{"t":"く"},{"t":"寝","r":"ね"},{"t":"るようにする"},{"t":" is not a decision to sleep early; it is arranging matters so that early sleeping is what happens. The habitual, effortful reading that textbooks list separately is simply what \"make it be that way\" means when it is said about your own conduct."}]'::jsonb),
  ('6dadd48c65511274a2f1c71005ce08c88de7df74f5d4867ab9c208341471e62d', 'したがって is the te-form of 従う, "to follow" or "to obey".', '[{"t":"したがって"},{"t":" is the te-form of "},{"t":"従","r":"したが"},{"t":"う"},{"t":", \"to follow\" or \"to obey\"."}]'::jsonb),
  ('30f3cf683c15c4cea413af9010b375e576108fba29611b02ef85efe77c40e77c', 'One verb, and its two ordinary senses are the two textbook meanings. 規則に従う is obeying a rule; 川に従って歩く is following a river along.

So 指示にしたがって is compliance and 年をとるにしたがって is keeping pace, and there is nothing else to memorise. It is the stiffer, more written cousin of につれて because 従う is the stiffer, more written verb.', '[{"t":"One verb, and its two ordinary senses are the two textbook meanings. "},{"t":"規則","r":"きそく"},{"t":"に"},{"t":"従","r":"したが"},{"t":"う"},{"t":" is obeying a rule; "},{"t":"川","r":"かわ"},{"t":"に"},{"t":"従","r":"したが"},{"t":"って"},{"t":"歩","r":"ある"},{"t":"く"},{"t":" is following a river along.\n\nSo "},{"t":"指","r":"ゆび"},{"t":"示","r":"しめ"},{"t":"にしたがって"},{"t":" is compliance and "},{"t":"年","r":"とせ"},{"t":"をとるにしたがって"},{"t":" is keeping pace, and there is nothing else to memorise. It is the stiffer, more written cousin of "},{"t":"につれて"},{"t":" because "},{"t":"従","r":"したが"},{"t":"う"},{"t":" is the stiffer, more written verb."}]'::jsonb),
  ('bd73fcb440031e5fec78734bec32fc3e83b51a2d9554c14ee2e5a8f1ba1d05ae', 'The tense inside decides everything: 行くことがある is occasional, 行ったことがある is experience.', '[{"t":"The tense inside decides everything: "},{"t":"行","r":"い"},{"t":"くことがある"},{"t":" is occasional, "},{"t":"行","r":"い"},{"t":"ったことがある"},{"t":" is experience."}]'::jsonb),
  ('959634ea6ef726d15ea98e105e1d7dfb31b56b313eedad321a8a2e7cf6eee1b7', 'Not a separate word after all: the dictionaries derive it from the assertive なり, turned into a conjunctive particle in the early modern period. 帰るなり寝てしまった.

