  ('d78e4032fb59c59efb6103d2beaa22360fd0c4ddf982e79a8ee628183d2baded', 'すぎる is the ordinary verb 過ぎる, "to pass by, to exceed", used as a suffix.', '[{"t":"すぎる"},{"t":" is the ordinary verb "},{"t":"過","r":"よ"},{"t":"ぎる"},{"t":", \"to pass by, to exceed\", used as a suffix."}]'::jsonb),
