  ('62a7a2e066c093dd444601c4e6626fc09515157d57111cb429c582805436b8a6', 'がち is 勝ち, from 勝つ: "to win, to prevail".', '[{"t":"がち"},{"t":" is "},{"t":"勝","r":"か"},{"t":"ち"},{"t":", from "},{"t":"勝","r":"か"},{"t":"つ"},{"t":": \"to win, to prevail\"."}]'::jsonb),
  ('31b6eca0afc1f079aa066c4e55f327d55602607d1599c011e78caf8ea18d12da', 'The thing that tends to happen is the thing that wins out. 病気がち is illness prevailing more often than not.

