  ('cded5fe39c7a780ef17df3675d726c6eb98ebbebe694e1aec3d08e1869665af1', 'ものだから is the noun 物 with だから, naming the reason as a plain thing.', '[{"t":"ものだから"},{"t":" is the noun "},{"t":"物","r":"もの"},{"t":" with "},{"t":"だから"},{"t":", naming the reason as a plain thing."}]'::jsonb),
  ('a65c4626ae5da27aa105e03dddac7c476c762ab2117588010cb349bf81e5b8a9', 'The same もの as ものだ at N3, where naming something as a thing makes it general and beyond argument.

