  ('967eec011233cd3f993de93cbf16d52845de4f5d3c578a01ff1b7dc21b1f37b5', 'よそ is 余所, somewhere else, another place entirely.', '[{"t":"よそ"},{"t":" is "},{"t":"余所","r":"よそ"},{"t":", somewhere else, another place entirely."}]'::jsonb),
  ('764ec6c9c0e0b2fca44568dd200500959c92755d24d26082cba502576d490ed4', 'よそ見 is looking away; よその人 is an outsider. をよそに puts the thing named somewhere other than where the actor is attending.

