  ('90012f31aef8a62d49d6e48ed7559356de27d4ce19ec7d0560dd1210ffe36b48', '否 is the classical word for "no"; the pattern is literally "whether or no".', '[{"t":"否","r":"ひ"},{"t":" is the classical word for \"no\"; the pattern is literally \"whether or no\"."}]'::jsonb),
  ('04b0faeacdaab2bdd32c039e821ec722e001f62bdcb30bf322d1c4e654ec9395', '否 survives in 安否, 否定 and in 否 read いな. かどうか says "whether, how, whether"; か否か says "whether or not", with the actual word for no in the middle.

