  ('c649ab71624ad74992e9529d8cfd7483ebb50e1ddefc660811103b11c7d0dded', '違いない is literally "there is no discrepancy", from 違う, to differ.', '[{"t":"違","r":"ちが"},{"t":"いない"},{"t":" is literally \"there is no discrepancy\", from "},{"t":"違","r":"たが"},{"t":"う"},{"t":", to differ."}]'::jsonb),
  ('c63239642782f863fc7dfd61c0151f9e8a2a9806c12fcff3684c8b74fdf5f538', '間違い is a mistake, a thing that came out different. に違いない says there is no gap between this and how matters are.

